import fs from "node:fs";

import { type APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

const TAG = "@REV-03";

type Json = Record<string, any>;

async function createVendor(api: APIRequestContext, name: string): Promise<Json> {
  const response = await api.post("/api/vendors", {
    data: {
      name,
      category: "services",
      contact_email: `${name.toLowerCase().replace(/[^a-z0-9]+/g, ".")}@example.test`,
    },
  });
  expect(response.status()).toBe(201);
  return response.json();
}

async function uploadDocument(
  api: APIRequestContext,
  vendorId: string,
  kind: "w9" | "insurance_certificate" | "contract",
  file: string,
): Promise<Json> {
  const response = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: { kind, file },
  });
  expect(response.status()).toBe(201);
  return response.json();
}

async function waitForExtracted(api: APIRequestContext, documentId: string): Promise<void> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const response = await api.get(`/api/documents/${documentId}`);
    expect(response.status()).toBe(200);
    const doc = (await response.json()) as Json;
    if (doc.status === "extracted") return;
    expect(doc.status, `document ${documentId} must not fail`).not.toBe("failed");
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  throw new Error(`document ${documentId} was not extracted in time`);
}

/** Uploads all three documents, waits for extraction, and submits the vendor for review. */
async function submitVendorForReview(
  api: APIRequestContext,
  name: string,
  insuranceFile: string,
): Promise<string> {
  const vendor = await createVendor(api, name);
  const vendorId: string = vendor.id;

  const docs = [
    await uploadDocument(api, vendorId, "w9", sample("w9.pdf")),
    await uploadDocument(api, vendorId, "insurance_certificate", sample(insuranceFile)),
    await uploadDocument(api, vendorId, "contract", sample("contract.pdf")),
  ];
  for (const doc of docs) {
    await waitForExtracted(api, doc.id);
  }

  const submit = await api.post(`/api/vendors/${vendorId}/submit`);
  expect(submit.status()).toBe(200);
  expect((await submit.json()).status).toBe("in_review");
  return vendorId;
}

test.describe("review queue ordering", () => {
  test(
    "vendor with an unparsed insurance expiry date is listed first, queue sorted by lowest confidence",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: two vendors in review; one has an insurance certificate whose expiry date
      // cannot be parsed (sample assumed to produce a null expiry_date field).
      const reviewer = await apiAs("reviewer");
      const unparsedName = uniqueName("REV03 Unparsed");
      const normalName = uniqueName("REV03 Normal");

      const unparsedId = await submitVendorForReview(
        reviewer,
        unparsedName,
        "insurance_unparseable_expiry.pdf",
      );
      const normalId = await submitVendorForReview(
        reviewer,
        normalName,
        "insurance_certificate.pdf",
      );

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const queue = (await response.json()) as Json[];

      // The whole queue is ordered by each item's lowest field confidence, ascending.
      for (let i = 1; i < queue.length; i++) {
        expect(queue[i].lowest_confidence).toBeGreaterThanOrEqual(queue[i - 1].lowest_confidence);
      }

      const unparsedIndex = queue.findIndex((item) => item.vendor_id === unparsedId);
      const normalIndex = queue.findIndex((item) => item.vendor_id === normalId);
      expect(unparsedIndex).toBeGreaterThanOrEqual(0);
      expect(normalIndex).toBeGreaterThanOrEqual(0);
      expect(unparsedIndex).toBeLessThan(normalIndex);

      // The unparsed-date vendor's lowest confidence is no higher than the other's.
      expect(queue[unparsedIndex].lowest_confidence).toBeLessThanOrEqual(
        queue[normalIndex].lowest_confidence,
      );
      expect(queue[unparsedIndex].vendor_name).toBe(unparsedName);
      expect(queue[normalIndex].vendor_name).toBe(normalName);
    },
  );
});
